def find_primes(n):
    # Initialize a boolean array to track prime status
    is_prime = [True] * (n + 1)
    p = 2

    while p * p <= n:
        if is_prime[p]:
            for i in range(p*p, n + 1, p):
                is_prime[i] = False
        p += 1

    # Extract prime numbers from the boolean array
    return [p for p in range(2, n + 1) if is_prime[p]]

