def is_prime(num):
    """Check if a number is prime."""
    if num <= 1:
        return False
    for i in range(2, int(num**0.5) + 1):
        if num % i == 0:
            return False
    return True

def find_primes(n):
    """Return a list of all primes up to n."""
    if n < 2:
        return []

    primes = []
    for num in range(2, n+1):
        if is_prime(num):
            primes.append(num)

    return primes

