    is_prime = [True] * (n + 1)
    p = 2
    while p * p <= n:
        if not is_prime[p]:
            for i in range(p * p, n + 1, p):
                is_prime[i] = False
        p += 1
    primes = []
    for num in range(2, n + 1):
        if is_prime[num]:
            primes.append(num)
    return primes

