def find_primes(n):
    # Helper function to check if a number is prime
    def is_prime(num):
        if num <= 1:
            return False
        for i in range(2, int(num**0.5) + 1):
            if num % i == 0:
                return False
        return True

    # Start from the smallest prime number, which is 2
    primes = [2]

    # Implement Sieve of Eratosthenes to find all primes up to n
    while len(primes) < n:
        if is_prime(primes[-1]):
            primes.append(primes[-1] + 1)
        for i in range(3, int(n**0.5) + 1, 2):
            if primes[i-1] % 2 == 0 and is_prime(primes[i-1]):
                primes[i-1] += 2

    return primes

