def sieve_of_eratosthenes(n):
    """Return a list of all prime numbers up to n."""
    is_prime = [True] * (n + 1)
    for i in range(2, int(n**0.5) + 1):
        if is_prime[i]:
            for j in range(i*i, n + 1, i):
                is_prime[j] = False
    return [num for num in range(2, n + 1) if is_prime[num]]

def segmented_sieve_of_eratosthenes(n):
    """Return a list of all prime numbers up to n."""
    is_prime = [True] * (n + 1)
    last_known_prime = None
    for i in range(2, int(n**0.5) + 1):
        if is_prime[i]:
            start = i * i
            while True:
                if is_prime[start]:
                    is_prime[start] = False
                    if last_known_prime != None and start >= last_known_prime:
                        break
                    last_known_prime = start
                start += i
    return [num for num in range(2, n + 1) if is_prime[num]]

